  --print-query         print out the current query as first line of output
  --ansi                enable ANSI color code support
  --height              display height in lines or percentage (e.g. '10', '50%')
`

const helpOutput = "\n" + helpBody

type cliOptions struct {
	help            bool
	version         bool
	query           *string
	rcfile          *string
	bufferSize      *int
	bufferSizeSet   bool
	null            bool
	initialIndex    *int
	initialFilter   *string
	prompt          *string
	layout          *string
	select1         bool
	exit0           bool
	selectAll       bool
	onCancel        *string
	selectionPrefix *string
	execCmd         *string
	printQuery      bool
	ansi            bool
	height          *string
	files           []string
}

func flagDisplayLong(name string) string {
	return "`" + name + "'"
}

func isOptionLike(s string, isIntFlag bool) bool {
	if s == "-" || s == "--" {
		return false
	}
	if strings.HasPrefix(s, "--") {
		if len(s) == 2 {
			return false
		}
		c := s[2]
		if c == '-' {
			return false
		}
		return true
	}
	if strings.HasPrefix(s, "-") {
		if len(s) < 2 {
			return false
		}
		// single dash, second char != '-' (since -- handled above, but --- also starts with --, handled)
		// Actually if s starts with "-" and len>1, and s[1]=='-', then it's "--..." already handled.
		// So here s[1] != '-'
		if isIntFlag {
			c := s[1]
			if c >= '0' && c <= '9' {
				return false
			}
			return true
		}
		return true
	}
	return false
}

func isFlagArg(s string) bool {
	if s == "-" || s == "--" {
		return false
	}
	if strings.HasPrefix(s, "--") {
		if len(s) == 2 {
			return false
		}
		if s[2] == '-' {
			return false
		}
		return true
	}
	if strings.HasPrefix(s, "-") {
		return true
	}
	return false
}

