}

func validateHeight(s string) error {
	if strings.HasSuffix(s, "%") {
		numStr := strings.TrimSuffix(s, "%")
		if numStr == "" {
			return fmt.Errorf("invalid height specification: \"%s\"", s)
		}
		n, err := strconv.ParseInt(numStr, 10, 64)
		if err != nil {
			return fmt.Errorf("invalid height specification: \"%s\"", s)
		}
		if n <= 0 {
			return fmt.Errorf("height percentage must be positive: \"%s\"", s)
		}
		if n > 100 {
			return fmt.Errorf("height percentage must not exceed 100: \"%s\"", s)
		}
		return nil
	}
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		return fmt.Errorf("invalid height specification: \"%s\"", s)
	}
	if n <= 0 {
		return fmt.Errorf("height must be positive: \"%s\"", s)
	}
	return nil
}

func isValidFilter(name string, cfg *Config) bool {
	switch name {
	case "IgnoreCase", "CaseSensitive", "SmartCase", "IRegexp", "Regexp", "Fuzzy":
