	if !isValidFilter(filterName, cfg) {
		return fmt.Errorf("failed to populate initial filter: failed to set filter: specified filter was not found")
	}
	cfg.InitialFilter = filterName
	if opt.prompt != nil {
		cfg.Prompt = *opt.prompt
	}
	if opt.layout != nil {
		cfg.Layout = *opt.layout
