		max := 0
		for _, iv := range intervals {
			if iv[1]-iv[0] > max {
				max = iv[1] - iv[0]
			}
		}
		return max
	}
	// Sensitive: same via intervals
	intervals := findFuzzyMatches(line, positives)
	max := 0
	for _, iv := range intervals {
		if iv[1]-iv[0] > max {
			max = iv[1] - iv[0]
		}
	}
	_ = lr
	_ = pr
	return max
}

func computeZoomLines(all []*Line, matches []*Line) []*Line {
	// Expand matches with 3 lines context before/after, deduplicate, preserve order (by all order)
	if len(matches) == 0 {
		return []*Line{}
	}
	// Build index map from Line pointer to idx in all
	idxMap := make(map[*Line]int)
	for i, l := range all {
		idxMap[l] = i
	}
	// Collect indices
	indices := make(map[int]bool)
	for _, m := range matches {
		idx, ok := idxMap[m]
		if !ok {
			continue
		}
		for d := -3; d <= 3; d++ {
			ni := idx + d
			if ni >= 0 && ni < len(all) {
				indices[ni] = true
			}
		}
	}
	var sorted []int
	for k := range indices {
		sorted = append(sorted, k)
	}
	sort.Ints(sorted)
	var res []*Line
	for _, i := range sorted {
		res = append(res, all[i])
	}
	return res
}

