	name := tcellToPeco(ev)
	// Handle pending sequences: t.pending holds previous parts?
	// Build candidate sequences
	// If pending non-empty, try pending+name
	if len(t.pending) > 0 {
		// Try pending + name as sequence
		candidate := strings.Join(append(append([]string{}, t.pending...), name), ",")
		// Check if candidate is exact match in keymap?
		if act, ok := t.keymap[candidate]; ok {
			// Check if candidate is also prefix of longer? If yes, longest wins, so wait? Need to check if any key starts with candidate+",".
			isPrefix := false
			prefix := candidate + ","
			for k := range t.keymap {
				if strings.HasPrefix(k, prefix) {
					isPrefix = true
					break
				}
			}
			if isPrefix {
