			}
			// Exact and not prefix, execute
			t.pending = nil
			t.statusMsg = ""
			return act, false, 0
		}
		// Check if candidate is prefix of longer?
		prefix := candidate + ","
		isPrefix := false
		for k := range t.keymap {
			if strings.HasPrefix(k, prefix) || k == candidate {
				// Actually k==candidate already checked (exact), so only prefix
				if strings.HasPrefix(k, prefix) {
					isPrefix = true
					break
				}
			}
		}
		// Also check if candidate itself is prefix (i.e., candidate is "C-x" and keymap has "C-x,C-c", then candidate is prefix)
