func parseANSIRunes(s string) ([]rune, []tcell.Style) {
	// Parse SGR sequences, return stripped runes and per-rune styles (with ANSI fg/bg/attrs, default otherwise)
	var runes []rune
	var styles []tcell.Style
	curStyle := tcell.StyleDefault
	i := 0
	for i < len(s) {
		if s[i] == '\x1b' && i+1 < len(s) && s[i+1] == '[' {
			// Find 'm'
			j := i + 2
			for j < len(s) && s[j] != 'm' && s[j] != '\x1b' {
				j++
			}
			if j < len(s) && s[j] == 'm' {
				seq := s[i+2 : j] // e.g., "31", "1;31", "38;5;123", etc.
				curStyle = applySGR(curStyle, seq)
				i = j + 1
				continue
			}
		}
		// Normal rune (decode UTF-8)
		r, size := utf8.DecodeRuneInString(s[i:])
		if r == utf8.RuneError && size == 1 {
			// Invalid, treat as byte?
			r = rune(s[i])
			size = 1
		}
		runes = append(runes, r)
		styles = append(styles, curStyle)
		i += size
	}
	return runes, styles
}

func applySGR(cur tcell.Style, seq string) tcell.Style {
	if seq == "" || seq == "0" {
		return tcell.StyleDefault
	}
	parts := strings.Split(seq, ";")
	// Handle extended colors 38;5;N, 48;5;N, 38;2;R;G;B, 48;2;R;G;B
	// Need to parse with index, since 38;5 consumes 3 parts, 38;2 consumes 5
	fg, bg, attr := cur.Decompose()
	// Decompose gives current fg/bg/attr, we'll update
	_ = fg
	_ = bg
	_ = attr
	// We'll build new style incrementally
	st := cur
	i := 0
	for i < len(parts) {
		p := parts[i]
		if p == "" {
			i++
			continue
		}
		n, err := atoi(p)
		if err != nil {
			i++
			continue
		}
		switch {
		case n == 0:
			st = tcell.StyleDefault
		case n == 1:
			st = st.Bold(true)
		case n == 4:
			st = st.Underline(true)
		case n == 7:
			st = st.Reverse(true)
		case n == 22:
			st = st.Bold(false)
		case n == 24:
			st = st.Underline(false)
		case n == 27:
			st = st.Reverse(false)
		case n >= 30 && n <= 37:
			var c tcell.Color
			switch n {
			case 30:
				c = tcell.ColorBlack
			case 31:
				c = tcell.ColorRed
			case 32:
				c = tcell.ColorGreen
			case 33:
				c = tcell.ColorYellow
			case 34:
				c = tcell.ColorBlue
			case 35:
				c = tcell.ColorPurple
			case 36:
				c = tcell.ColorTeal
			case 37:
				c = tcell.ColorWhite
			}
			st = st.Foreground(c)
		case n == 39:
			st = st.Foreground(tcell.ColorDefault)
		case n >= 40 && n <= 47:
			var c tcell.Color
			switch n {
			case 40:
				c = tcell.ColorBlack
			case 41:
				c = tcell.ColorRed
			case 42:
				c = tcell.ColorGreen
			case 43:
				c = tcell.ColorYellow
			case 44:
				c = tcell.ColorBlue
			case 45:
				c = tcell.ColorPurple
			case 46:
				c = tcell.ColorTeal
			case 47:
				c = tcell.ColorWhite
			}
