		case n == 49:
			st = st.Background(tcell.ColorDefault)
		case n >= 90 && n <= 97:
			// Bright fg: map to palette 8-15
			c := tcell.PaletteColor(n - 90 + 8)
			st = st.Foreground(c)
		case n >= 100 && n <= 107:
			c := tcell.PaletteColor(n - 100 + 8)
			st = st.Background(c)
		case n == 38:
