					}
					i += 2
				} else if parts[i+1] == "2" && i+4 < len(parts) {
					r, err1 := atoi(parts[i+2])
					g, err2 := atoi(parts[i+3])
					b, err3 := atoi(parts[i+4])
					if err1 == nil && err2 == nil && err3 == nil {
						st = st.Foreground(tcell.NewRGBColor(int32(r), int32(g), int32(b)))
					}
					i += 4
				}
			}
		case n == 48:
			if i+1 < len(parts) {
				if parts[i+1] == "5" && i+2 < len(parts) {
					if nn, err := atoi(parts[i+2]); err == nil && nn >= 0 && nn <= 255 {
						st = st.Background(tcell.PaletteColor(nn))
					}
					i += 2
				} else if parts[i+1] == "2" && i+4 < len(parts) {
					r, err1 := atoi(parts[i+2])
					g, err2 := atoi(parts[i+3])
					b, err3 := atoi(parts[i+4])
					if err1 == nil && err2 == nil && err3 == nil {
						st = st.Background(tcell.NewRGBColor(int32(r), int32(g), int32(b)))
					}
					i += 4
				}
			}
		default:
			// Ignore others (e.g., 2 dim, 3 italic, 9 strike, etc.)
		}
		i++
	}
	return st
}

